public int PathSumIII(TreeNode? root, int targetSum)
{
    var prefixCount = new Dictionary<long, int> { [0] = 1 };
    return DFS(root, 0, targetSum, prefixCount);
}

private int DFS(TreeNode? node, long currSum, int target, Dictionary<long, int> prefix)
{
    if (node == null) return 0;
    currSum += node.Val;
    int count = prefix.GetValueOrDefault(currSum - target);
    prefix[currSum] = prefix.GetValueOrDefault(currSum, 0) + 1;
    count += DFS(node.Left, currSum, target, prefix);
    count += DFS(node.Right, currSum, target, prefix);
    prefix[currSum]--;
    return count;
}
